R = {
    "cochinita-pibil": ("Cochinita pibil", "Mexiko", "4 h (+ 1 Nacht Marinieren)", "8 Personen",
        "Gezupftes Schweinefleisch aus Yucatán: in Achiote und Zitrussaft mariniert und langsam in Bananenblättern gegart, bis es zerfällt.",
        ["2 kg Schweineschulter in großen Stücken", "100 g Achiote-Paste (Annatto)", "Saft von 4 Orangen und 2 Limetten, 4 Knoblauchzehen, je 1 Teelöffel Oregano und Kreuzkümmel, Salz", "Bananenblätter", "Maistortillas, in Limettensaft eingelegte rote Zwiebel und Habanero-Chili zum Servieren"],
        ["Die Achiote-Paste im Orangen- und Limettensaft mit dem zerdrückten Knoblauch, Oregano, Kreuzkümmel und Salz auflösen.", "Das Fleisch mit der Marinade bedecken und über Nacht in den Kühlschrank stellen.", "Eine Form mit über der Flamme geschmeidig gemachten Bananenblättern auslegen, das Fleisch mit der Marinade hineingeben und die Blätter darüber schlagen.", "Mit Alufolie abdecken und bei 160 °C 4 Stunden im Ofen garen, bis sich das Fleisch mit der Gabel zerzupfen lässt.", "Das Fleisch im eigenen Saft zerzupfen und in warmen Tortillas mit der eingelegten Zwiebel und Chili servieren."]),
    "tamales": ("Hähnchen-Tamales", "Mexiko", "2 h 30", "6 Personen",
        "Mexikos Päckchen aus Maisteig, gefüllt mit Hähnchen in scharfer Soße und in Maisblättern gedämpft.",
        ["500 g Maismehl für Tamales (Masa)", "20 getrocknete Maisblätter", "500 g gegartes, gezupftes Hähnchen", "1 Dose Chipotle-Chilis in Adobo-Soße (oder Salsa verde)", "150 g Schmalz oder Pflanzenfett, 500 ml Hühnerbrühe, 1 Teelöffel Backpulver, Salz"],
        ["Die Maisblätter 30 Minuten in heißem Wasser einweichen.", "Das Fett hell aufschlagen, dann Masa, Backpulver, Salz und nach und nach die Brühe zugeben, bis ein weicher Teig entsteht, von dem eine kleine Kugel im Wasser schwimmt.", "Das Hähnchen mit den gehackten Chipotle-Chilis und etwas Soße mischen.", "2 Löffel Teig auf jedes Blatt streichen, einen Löffel Hähnchen daraufgeben, die Seiten und dann das untere Ende einschlagen.", "Stehend 1 h 15 dämpfen, bis sich der Teig sauber vom Blatt löst."]),
    "gallo-pinto": ("Gallo pinto", "Costa Rica und Nicaragua", "30 min", "4 Personen",
        "Das Frühstück Mittelamerikas: Reis vom Vortag, angebraten mit schwarzen Bohnen, Zwiebel, Paprika und Koriander.",
        ["2 Tassen gekochte schwarze Bohnen mit etwas Kochflüssigkeit", "3 Tassen weißer Reis vom Vortag", "1 Zwiebel und 1 rote Paprika, gehackt, 2 Knoblauchzehen", "1 Bund Koriander", "2 Esslöffel Öl, Salz; Lizano- oder Worcestershiresoße nach Geschmack"],
        ["Zwiebel, Paprika und Knoblauch 5 Minuten im Öl anbraten.", "Die Bohnen mit ihrer Flüssigkeit zugeben und 3 Minuten einkochen lassen.", "Den Reis zugeben und vorsichtig mischen, bis er die Farbe der Bohnen annimmt.", "Mit Salz und einem Spritzer Lizano-Soße würzen.", "Mit Koriander bestreuen und mit Eiern, gebratener reifer Kochbanane und Sauerrahm servieren."]),
    "mangu": ("Mangú", "Dominikanische Republik", "40 min", "4 Personen",
        "Dominikanisches Püree aus grüner Kochbanane mit Essig-Zwiebeln, serviert mit den „drei Schlägen“: Salami, gebratener Käse und Ei.",
        ["4 grüne Kochbananen", "2 rote Zwiebeln in Ringen", "3 Esslöffel Butter", "Essig, Öl, Salz", "Bratkäse, Salami und Eier zum Servieren"],
        ["Die Kochbananen schälen, in Stücke schneiden und 20 Minuten in Salzwasser kochen.", "Die Zwiebeln in etwas Öl andünsten, einen Schuss Essig und Salz zugeben.", "Die Kochbananen mit der Butter und etwas kaltem Kochwasser zu einem glatten Püree stampfen.", "Salami- und Käsescheiben braten und die Eier zubereiten.", "Das Püree mit den Zwiebeln bedeckt servieren, dazu Salami, Käse und Eier."]),
    "patacones": ("Patacones", "Kolumbien", "30 min", "4 Personen",
        "Zweimal frittierte, knusprige Taler aus grüner Kochbanane, mit Hogao (Tomaten-Frühlingszwiebel-Soße) und Avocado.",
        ["3 grüne Kochbananen", "Öl zum Frittieren", "Salz und 1 zerdrückte Knoblauchzehe in einer Schüssel Wasser", "Hogao: 2 Tomaten, 4 Frühlingszwiebeln, Öl, Salz", "1 Avocado"],
        ["Die Kochbananen schälen und in 4 cm lange Stücke schneiden.", "5 Minuten in mittelheißem Öl frittieren, ohne sie zu bräunen, dann abtropfen lassen.", "Zwischen zwei Brettern oder mit dem Boden eines Glases flach drücken und in das gesalzene Knoblauchwasser tauchen.", "In sehr heißem Öl erneut frittieren, bis sie goldbraun und knusprig sind; salzen.", "Hogao: die gehackten Tomaten und Frühlingszwiebeln 10 Minuten im Öl schmoren. Mit zerdrückter Avocado servieren."]),
    "bolon-verde": ("Bolón de verde", "Ecuador", "40 min", "4 Personen",
        "Kugeln aus grüner Kochbanane von Ecuadors Küste, mit Käse und knusprigem Schweinefleisch gestampft und in der Pfanne gebräunt.",
        ["4 grüne Kochbananen", "150 g Grillkäse oder Mozzarella, gewürfelt", "150 g Chicharrón (frittiertes Schweinefleisch) oder Speck", "2 Esslöffel Butter oder Schmalz", "½ Teelöffel Achiote (Annatto), Salz"],
        ["Die Kochbananen in Stücke schneiden und 20 Minuten in Salzwasser kochen.", "Das Schweinefleisch in kleinen Stücken anbraten und das Fett aufbewahren.", "Die heißen Kochbananen mit Butter, Achiote und etwas Fett stampfen.", "Käse und Fleisch untermischen und orangengroße Kugeln formen.", "In etwas Öl in der Pfanne bräunen. Zum Frühstück mit einem Ei und Kaffee servieren."]),
    "yuca-mojo": ("Yuca con mojo", "Kuba", "45 min", "4 Personen",
        "Maniok auf kubanische Art: weich gekocht und mit einer heißen Mojo-Soße aus Knoblauch, Zitrussaft und Zwiebel übergossen.",
        ["1 kg Maniok (Yuca), frisch oder tiefgekühlt", "8 Knoblauchzehen", "Saft von 2 Orangen und 2 Limetten", "1 Zwiebel in dünnen Ringen", "100 ml Olivenöl, 1 Teelöffel Kreuzkümmel, Salz"],
        ["Den Maniok schälen, in Stücke schneiden und die holzige Mitte entfernen.", "25 bis 30 Minuten in Salzwasser kochen, bis er aufplatzt; abgießen.", "Den Knoblauch mit Salz und Kreuzkümmel zerdrücken und im Orangen- und Limettensaft verrühren.", "Das Öl erhitzen, die Zwiebel darin 3 Minuten weich dünsten und die Knoblauchmischung neben dem Herd zugießen.", "Die heiße Mojo-Soße über den Maniok gießen und mit Schweinebraten oder Reis und Bohnen servieren."]),
    "sopa-quinoa": ("Quinoasuppe", "Peru und Bolivien", "45 min", "6 Personen",
        "Die Suppe der Anden: Quinoa, Kartoffeln und Gemüse in einer mit Ají gewürzten Brühe, mit Frischkäse.",
        ["200 g Quinoa, gründlich gespült", "3 Kartoffeln und 2 Karotten, gewürfelt", "1 Zwiebel, 2 Knoblauchzehen, 1 Esslöffel Ají-Paste (oder Paprikapulver)", "2 Liter Hühner- oder Gemüsebrühe, 1 Tasse Erbsen oder Saubohnen", "Koriander oder Petersilie, gewürfelter Frischkäse, Salz"],
        ["Zwiebel, Knoblauch und Ají 5 Minuten in etwas Öl anbraten.", "Brühe und Quinoa zugeben; 15 Minuten kochen.", "Kartoffeln und Karotten zugeben; 15 Minuten kochen.", "Erbsen oder Saubohnen zugeben, weitere 5 Minuten kochen und salzen.", "Mit gehacktem Koriander und einigen Würfeln Frischkäse servieren."]),
    "ful-medames": ("Ful medames", "Ägypten", "20 min", "4 Personen",
        "Ägyptens Frühstück: langsam gegarte Saubohnen, zerdrückt mit Knoblauch, Kreuzkümmel, Zitrone und Olivenöl.",
        ["2 Dosen Saubohnen (Ful) à 400 g", "2 Knoblauchzehen, 1 Teelöffel Kreuzkümmel, Salz", "Saft von 1 Zitrone", "4 Esslöffel Olivenöl", "Tomate, Petersilie, Zwiebel, hartgekochte Eier und Pitabrot zum Servieren"],
        ["Die Bohnen mit ihrer Flüssigkeit 10 Minuten bei schwacher Hitze erwärmen.", "Den Knoblauch mit Salz und Kreuzkümmel zerdrücken.", "Einen Teil der Bohnen grob zerdrücken, Knoblauch und Zitronensaft zugeben, bei Bedarf etwas heißes Wasser.", "In eine flache Schale geben und großzügig mit Olivenöl beträufeln.", "Mit gehackter Tomate und Petersilie, Zwiebel und Ei garnieren; mit warmem Pitabrot servieren."]),
    "chorba-frik": ("Chorba frik", "Algerien", "1 h 15", "6 Personen",
        "Algeriens Ramadan-Suppe: Lamm, Tomate und geschroteter grüner Weizen, mit Koriander und Minze gewürzt.",
        ["500 g Lammfleisch in kleinen Stücken", "100 g Frik (geschroteter grüner Weizen)", "1 Dose Kichererbsen", "2 geriebene Tomaten und 1 Esslöffel Tomatenmark", "1 Zwiebel, 1 Bund Koriander, getrocknete Minze, Zimt, Paprikapulver, Salz, Pfeffer"],
        ["Lamm und gehackte Zwiebel in etwas Öl mit Zimt, Paprika, Salz und Pfeffer anbraten.", "Tomaten, Tomatenmark, die Hälfte des gehackten Korianders und 2 Liter Wasser zugeben; 40 Minuten kochen.", "Die abgetropften Kichererbsen zugeben und den Frik einrieseln lassen; 20 Minuten kochen und gelegentlich umrühren.", "Den restlichen Koriander und eine Prise getrocknete Minze zugeben.", "Mit einem Zitronenschnitz, Datteln und Brot servieren."]),
    "misir-wat": ("Misir wat", "Äthiopien", "45 min", "4 Personen",
        "Äthiopischer Eintopf aus roten Linsen mit Berbere, rot und scharf, auf Injera serviert.",
        ["250 g rote Linsen", "2 rote Zwiebeln, sehr fein gehackt", "2 Esslöffel Berbere (oder Chilipulver mit Paprika und Gewürzen)", "3 Knoblauchzehen", "1 Stück Ingwer, 4 Esslöffel Öl oder geklärte Butter, Salz"],
        ["Die Zwiebeln ohne Fett bei schwacher Hitze 10 Minuten unter Rühren weich garen.", "Öl, geriebenen Knoblauch und Ingwer, dann das Berbere zugeben; 3 Minuten garen.", "Die gespülten Linsen und 750 ml Wasser zugeben.", "25 Minuten bei schwacher Hitze unter Rühren köcheln, bis die Linsen zerfallen; salzen.", "Mit Injera, Brot oder Reis servieren."]),
    "githeri-chapati": ("Githeri und Chapati", "Kenia", "1 h 30", "6 Personen",
        "Kenias Alltagsgericht: Mais und Bohnen mit Tomate und Gemüse geschmort, dazu blättrige Chapatis.",
        ["2 Tassen getrockneter weißer Mais und 1 Tasse Kidneybohnen, über Nacht eingeweicht (oder aus der Dose)", "2 Tomaten, 1 Zwiebel, 1 Karotte, 1 Kartoffel", "Chapati: 500 g Mehl", "1 Teelöffel Salz, 1 Esslöffel Zucker, 300 ml lauwarmes Wasser", "Öl, 1 Teelöffel Currypulver, Salz"],
        ["Den eingeweichten Mais und die Bohnen 1 Stunde in Wasser weich kochen; abgießen.", "Zwiebel, gewürfelte Karotte und Kartoffel im Öl anbraten, Tomaten und Curry zugeben, dann Mais und Bohnen; 15 Minuten schmoren.", "Chapati: Mehl, Salz, Zucker, 2 Löffel Öl und Wasser 10 Minuten kneten und 30 Minuten ruhen lassen.", "Den Teig ausrollen, mit Öl bestreichen, zu einer Rolle und dann zu einer Schnecke formen; ruhen lassen und zu dünnen Fladen ausrollen.", "Die Chapatis in einer trockenen Pfanne backen, beidseitig mit Öl bestreichen, bis sie goldbraun sind. Mit dem Githeri servieren."]),
    "salade-fonio": ("Fonio-Salat", "Senegal und Mali", "30 min", "4 Personen",
        "Fonio, ein uraltes Getreide der Sahelzone, zu lockeren Körnern gegart und als frischer Salat mit Gemüse und Zitrone serviert.",
        ["250 g Fonio", "1 Gurke und 2 Tomaten, gewürfelt", "1 rote Zwiebel und 1 Paprika, gehackt", "Saft von 2 Zitronen, 4 Esslöffel Öl", "Minze und Petersilie, Salz, Pfeffer"],
        ["Den Fonio mehrmals spülen und gut abtropfen lassen.", "10 Minuten dämpfen (oder in 400 ml kochendes Salzwasser geben, zudecken und 5 Minuten neben dem Herd quellen lassen).", "Mit einer Gabel und etwas Öl auflockern und abkühlen lassen.", "Gurke, Tomaten, Zwiebel und Paprika zugeben.", "Mit Zitronensaft, Öl, Salz, Pfeffer, gehackter Minze und Petersilie anmachen. Kalt servieren."]),
    "bouye": ("Bouye (Baobab-Saft)", "Senegal", "15 min (+ 1 h kühlen)", "6 Personen",
        "Das Fruchtmark des Affenbrotbaums, zu einem cremigen, süß-säuerlichen Getränk verrührt und eiskalt serviert.",
        ["200 g Baobab-Fruchtpulver und 1 Liter kaltes Wasser", "250 ml gezuckerte Kondensmilch (oder 150 g Zucker)", "Zucker nach Geschmack", "1 Päckchen Vanillezucker", "Orangenblütenwasser oder eine Prise Muskat (nach Belieben)"],
        ["Das Baobabpulver in die Hälfte des kalten Wassers rühren und 15 Minuten stehen lassen.", "Gut verrühren, damit sich das Fruchtmark löst, dann durch ein feines Sieb gießen.", "Restliches Wasser, Kondensmilch, Zucker und Vanillezucker zugeben.", "Mit etwas Orangenblütenwasser oder Muskat aromatisieren.", "1 Stunde kühlen und eiskalt servieren."]),
    "gboma-dessi": ("Gboma dessi", "Togo und Ghana", "1 h", "6 Personen",
        "Togos Spinateintopf: Gboma-Blätter in Tomatensoße mit Palmöl, mit Fleisch und Räucherfisch.",
        ["1 kg Spinat (Gboma), frisch oder tiefgekühlt", "500 g Rindfleisch in Stücken", "1 Räucherfisch und 2 Esslöffel gemahlene getrocknete Garnelen", "3 Tomaten, 2 Zwiebeln, 1 Esslöffel Tomatenmark", "100 ml Palmöl, Chili, Ingwer, 1 Brühwürfel, Salz"],
        ["Das Fleisch mit einer Zwiebel, Ingwer, Brühwürfel und Salz in wenig Wasser 30 Minuten kochen.", "Die andere Zwiebel im Palmöl anbraten, pürierte Tomaten, Tomatenmark und Chili zugeben; 10 Minuten kochen.", "Fleisch mit Brühe, zerpflückten Fisch und Garnelen zugeben; 10 Minuten köcheln.", "Den Spinat waschen, hacken, ausdrücken und in die Soße geben.", "Ohne Deckel 10 Minuten garen. Mit Akoumé (Maisteig), Reis oder Yams servieren."]),
    "to-sauce-gombo": ("Tô mit Okra-Soße", "Burkina Faso und Mali", "1 h", "6 Personen",
        "Der feste, glatte Hirsebrei aus Burkina Faso und Mali mit einer zähflüssigen Soße aus Okra, Fleisch und Soumbala.",
        ["500 g Hirse- oder Sorghummehl (oder Maismehl)", "500 g frische Okra oder 3 Esslöffel Okrapulver", "500 g Rind- oder Hammelfleisch in Stücken", "1 Esslöffel Soumbala (oder 1 Brühwürfel)", "2 Tomaten, 1 Zwiebel, Chili, Salz"],
        ["Soße: das Fleisch mit Zwiebel, Tomaten, Soumbala und Salz in 1 Liter Wasser 40 Minuten kochen.", "Die geschnittene Okra (oder das Pulver) und Chili zugeben; 15 Minuten unter Rühren kochen, bis die Soße Fäden zieht.", "Tô: ein Drittel des Mehls in 500 ml kaltem Wasser verrühren, in 1 Liter kochendes Wasser gießen und 10 Minuten unter Rühren kochen.", "Eine Schüssel dieses Breis abnehmen, dann das restliche Mehl einrieseln lassen und kräftig mit einem Spatel rühren; mit dem abgenommenen Brei lockern, wenn er zu fest ist.", "Zugedeckt 5 Minuten bei schwacher Hitze ziehen lassen, in einer nassen Schüssel zu Kugeln formen und mit der Soße servieren."]),
    "banku-okro": ("Banku mit Okrasuppe", "Ghana", "1 h", "6 Personen",
        "Ghanaisches Banku, ein leicht säuerlicher Teig aus fermentiertem Mais und Maniok, mit Okrasuppe und Fisch.",
        ["1 kg Banku-Mix (Teig aus Mais und Maniok)", "300 g Okra", "500 g Fisch (Tilapia oder Makrele) oder Rindfleisch", "3 Tomaten, 2 Zwiebeln, Chili, Ingwer", "2 Esslöffel gemahlene getrocknete Garnelen, 100 ml Palmöl, 1 Brühwürfel, Salz"],
        ["Banku: den Teig in etwa 750 ml Salzwasser glatt rühren.", "Bei mittlerer Hitze 20 Minuten ununterbrochen mit einem Spatel rühren, bis er dick und glatt ist; zu Kugeln formen.", "Suppe: eine Zwiebel im Palmöl anbraten, die mit der anderen Zwiebel, Ingwer und Chili pürierten Tomaten zugeben; 10 Minuten kochen.", "500 ml Wasser, Fisch, Garnelen und Brühwürfel zugeben; 10 Minuten kochen.", "Die Okra in Scheiben zugeben und 8 Minuten kochen. Mit dem Banku servieren."]),
    "ngai-ngai": ("Ngai-ngai mit Salzfisch", "DR Kongo und Kongo", "1 h (+ 2 h Einweichen)", "6 Personen",
        "Säuerliche Blätter der Rosella (Ngai-ngai), in Palmöl mit Salzfisch geschmort: ein Klassiker aus Kinshasa und Brazzaville.",
        ["500 g Rosellablätter (Ngai-ngai), frisch oder tiefgekühlt", "300 g Salzfisch", "100 ml Palmöl", "2 kleine Auberginen (nach Belieben)", "2 Zwiebeln, 2 Knoblauchzehen, Chili, Salz"],
        ["Den Salzfisch 2 Stunden einweichen, dabei das Wasser wechseln, dann zerpflücken.", "Die Blätter waschen, hacken und 15 Minuten in wenig Wasser kochen; gut ausdrücken.", "Zwiebeln und Knoblauch im Palmöl anbraten.", "Blätter, Fisch, gewürfelte Auberginen und Chili zugeben; 25 Minuten bei schwacher Hitze schmoren.", "Vor dem Salzen abschmecken, der Fisch ist schon salzig. Mit Chikwangue, Fufu oder Reis servieren."]),
    "sorrel": ("Sorrel (Weihnachtsgetränk)", "Jamaika", "30 min (+ 1 Nacht ziehen lassen)", "8 Personen",
        "Jamaikas rubinrotes Weihnachtsgetränk: Hibiskuskelche, mit viel Ingwer und Gewürzen aufgegossen und eiskalt serviert.",
        ["2 Tassen getrocknete Hibiskuskelche (Sorrel)", "1 großes Stück Ingwer, gerieben, und 2 Liter Wasser", "6 Gewürznelken, 1 Zimtstange, einige Pimentkörner", "1 Tasse Zucker", "Limettensaft; ein Schuss Rum (nach Belieben, für Erwachsene)"],
        ["Die Kelche abspülen.", "Das Wasser mit Ingwer, Nelken, Zimt und Piment aufkochen.", "Den Sorrel zugeben, den Herd ausschalten und zugedeckt über Nacht ziehen lassen.", "Abseihen, süßen und nach Geschmack Limettensaft zugeben.", "Auf Eis servieren, für Erwachsene mit einem Schuss Rum."]),
    "mayi-moulen": ("Mayi moulen mit sòs pwa", "Haiti", "40 min", "4 Personen",
        "Haitianisches Maismehl, wie eine cremige Polenta gegart und mit einer Bohnensoße (sòs pwa) serviert.",
        ["2 Tassen mittelfeines Maismehl (Mayi moulen)", "1 Dose rote oder schwarze Bohnen", "1 Tasse Kokosmilch (nach Belieben)", "2 Esslöffel Epis (haitianische Würzpaste), Thymian, 2 Gewürznelken", "1 Zwiebel, 2 Esslöffel Öl, Salz"],
        ["Sòs pwa: die Bohnen mit ihrer Flüssigkeit pürieren und mit der Hälfte des Epis, Thymian und Nelken 15 Minuten erhitzen, bis die Soße eindickt.", "Zwiebel und restliches Epis im Öl anbraten, 4 Tassen Wasser (oder Wasser und Kokosmilch) und Salz zugeben; aufkochen.", "Das Maismehl unter ständigem Rühren einrieseln lassen.", "Zugedeckt 20 Minuten bei sehr schwacher Hitze garen, gelegentlich umrühren, bis der Mais weich ist.", "Das Mayi moulen mit sòs pwa überzogen servieren, dazu Räucherhering oder Avocado."]),
}
